const token=location.hash.slice(1);history.replaceState(null,'',location.pathname);const form=document.getElementById('setup'),result=document.getElementById('result');if(!token){result.textContent='Open your private setup link to continue.';form.hidden=true;}form.onsubmit=async event=>{event.preventDefault();const button=form.querySelector('button');button.disabled=true;try{const pin=document.getElementById('pin').value,confirm=document.getElementById('confirm').value;if(pin!==confirm)throw Error('The PIN entries do not match.');const response=await fetch('/api/owner/pin',{method:'POST',headers:{'Content-Type':'application/json','x-owner-pin-setup':token},body:JSON.stringify({pin,confirm}),cache:'no-store'});const data=await response.json();if(!response.ok)throw Error(data.error||'PIN could not be saved.');form.reset();form.hidden=true;result.textContent='Your owner PIN is saved. Keep it private. Phone activation is the next setup step.';}catch(e){result.textContent=e.message;}finally{button.disabled=false;}};